export default {"intro":{"ageQ":"Сколько лет ребёнку?","ages":["3-5","6-8","9-12"],"genderQ":"Это мальчик или девочка?","genders":["Мальчик","Девочка"]},"questions":[{"id":"q1","text":"Чем ребёнок занимается, когда его никто не занимает?","options":[{"scale":"builder","text":"Что-то строит или собирает"},{"scale":"storyteller","text":"Придумывает истории, говорит за игрушки"},{"scale":"mover","text":"Бегает, лазает, прыгает"},{"scale":"artist","text":"Рисует, лепит, вырезает"},{"scale":"inventor","text":"Разбирает вещи или ставит опыты: что будет, если…"},{"scale":"explorer","text":"Рассматривает, наблюдает, что-то ищет и находит"},{"scale":"leader","text":"Зовёт других и придумывает общую игру"},{"scale":"helper","text":"Идёт помогать вам или заботится о ком-то"}]},{"id":"q2","text":"Какие игрушки занимают его дольше всего?","options":[{"scale":"inventor","text":"Головоломки, наборы для опытов"},{"scale":"helper","text":"Куклы, зверушки, игры в «дочки-матери» и доктора"},{"scale":"leader","text":"Игры с правилами, в которые играют с другими"},{"scale":"explorer","text":"Находки с улицы: камни, жуки, палки"},{"scale":"builder","text":"Конструкторы и кубики"},{"scale":"storyteller","text":"Книги, фигурки и игрушки для историй"},{"scale":"artist","text":"Краски, пластилин, наборы для творчества"},{"scale":"mover","text":"Мяч, самокат, скакалка: всё для движения"}]},{"id":"q3","text":"О чём он чаще всего спрашивает «почему»?","options":[{"scale":"inventor","text":"Как устроены вещи и механизмы"},{"scale":"explorer","text":"Про животных, природу, космос"},{"scale":"storyteller","text":"Что значат слова, чем кончилась история"},{"scale":"helper","text":"Почему люди грустят, злятся, радуются"}]},{"id":"q4","text":"Что он выбирает на экране, если можно выбрать самому?","options":[{"scale":"builder","text":"Игры, где строят миры и города"},{"scale":"artist","text":"Рисование, музыку, как что-то мастерят"},{"scale":"mover","text":"Спорт, танцы, трюки"},{"scale":"leader","text":"Соревнования и челленджи"}]},{"id":"q5","text":"Что он делает на детской площадке?","options":[{"scale":"mover","text":"Сразу лезет на самое высокое"},{"scale":"leader","text":"Собирает детей и придумывает игру"},{"scale":"explorer","text":"Обходит все углы, что-то находит"},{"scale":"helper","text":"Опекает младших, делится"}]},{"id":"q6","text":"Какие книги и истории он любит?","options":[{"scale":"storyteller","text":"Сказки и приключения с героями"},{"scale":"inventor","text":"Энциклопедии и «как это работает»"},{"scale":"artist","text":"Где красивые картинки, сам их разглядывает"},{"scale":"builder","text":"Про машины, технику, стройку"}]},{"id":"q7","text":"Какой подарок он выберет сам?","options":[{"scale":"builder","text":"Конструктор"},{"scale":"artist","text":"Набор для творчества или инструмент"},{"scale":"inventor","text":"Набор юного учёного"},{"scale":"mover","text":"Мяч, самокат, велосипед"}]},{"id":"q8","text":"Чем он гордится больше всего?","options":[{"scale":"leader","text":"Победил или был главным"},{"scale":"helper","text":"Кому-то помог"},{"scale":"storyteller","text":"Выступил, рассказал, рассмешил"},{"scale":"explorer","text":"Нашёл или узнал что-то новое"}]},{"id":"q9","text":"Сломалась любимая игрушка. Что он сделает?","options":[{"scale":"builder","text":"Пытается починить"},{"scale":"inventor","text":"Разбирает, чтобы посмотреть, что внутри"},{"scale":"artist","text":"Превращает во что-то другое"},{"scale":"storyteller","text":"Придумывает историю, что с ней случилось"}]},{"id":"q10","text":"Новая компания детей. Как он себя ведёт?","options":[{"scale":"leader","text":"Предлагает, во что играть"},{"scale":"helper","text":"Находит одного ребёнка и дружит с ним"},{"scale":"explorer","text":"Сначала наблюдает и осматривается"},{"scale":"mover","text":"Сразу включается в беготню"}]},{"id":"q11","text":"Задача не получается. Что он делает?","options":[{"scale":"inventor","text":"Пробует другой способ"},{"scale":"builder","text":"Делает шаг за шагом, пока не получится"},{"scale":"leader","text":"Зовёт других делать вместе"},{"scale":"storyteller","text":"Рассуждает вслух, обсуждает"}]},{"id":"q12","text":"Проиграл в игре. Что дальше?","options":[{"scale":"mover","text":"Требует реванш прямо сейчас"},{"scale":"leader","text":"Спорит о правилах, договаривается"},{"scale":"helper","text":"Поздравляет, переживает за других"},{"scale":"artist","text":"Уходит заниматься своим делом"}]},{"id":"q13","text":"Свободный день. Что он выберет?","options":[{"scale":"explorer","text":"Лес, зоопарк, музей"},{"scale":"mover","text":"Бассейн, батуты, спорт"},{"scale":"artist","text":"Мастерить, рисовать, музыку"},{"scale":"storyteller","text":"Театр, кино, книги"}]},{"id":"q14","text":"Рядом кто-то плачет. Что он делает?","options":[{"scale":"helper","text":"Подходит утешить"},{"scale":"leader","text":"Зовёт взрослого, берёт дело в свои руки"},{"scale":"storyteller","text":"Расспрашивает, что случилось"},{"scale":"inventor","text":"Пытается устранить причину"}]},{"id":"q15","text":"Собираетесь в поездку. Как он собирается?","options":[{"scale":"builder","text":"Складывает вещи по порядку"},{"scale":"explorer","text":"Расспрашивает, куда едем и что там есть"},{"scale":"artist","text":"Выбирает наряд и любимые мелочи"},{"scale":"mover","text":"Не может усидеть, уже у двери"}]},{"id":"q16","text":"Ему дали коробку с разными деталями. Что он сделает?","options":[{"scale":"builder","text":"Сразу что-то строит"},{"scale":"inventor","text":"Сортирует и проверяет, что для чего"},{"scale":"helper","text":"Придумывает, кому из этого сделать подарок"},{"scale":"explorer","text":"Рассматривает каждую и спрашивает, откуда она"}]}],"sliders":{"labels":["Редко","Иногда","Часто","Почти всегда","Всегда"],"items":[{"id":"energy","text":"У ребёнка много энергии, ему трудно усидеть на месте"},{"id":"boldness","text":"Смело идёт в новое: место, люди, занятие"},{"id":"persistence","text":"Доводит начатое до конца, даже когда трудно"},{"id":"sensitivity","text":"Тонко чувствует настроение других и остро переживает"},{"id":"sociability","text":"Легко заводит знакомства и любит быть среди людей"},{"id":"pace","text":"Любит, когда всё быстро, и не любит ждать"}]},"goal":{"text":"Что вам важнее всего узнать?","options":[{"id":"activity","text":"Какой кружок или секцию выбрать"},{"id":"strengths","text":"В чём он сильнее всего"},{"id":"future","text":"Что попробовать с ребёнком дальше"},{"id":"character","text":"Как найти к нему подход"}]},"types":{"builder":{"name":"Строитель","nameF":"Строитель","tagline":"Думает руками и видит, как собрать целое из частей","careers":"инженер, архитектор, механик, столяр"},"inventor":{"name":"Изобретатель","nameF":"Изобретатель","tagline":"Хочет знать, как всё устроено, и пробует по-своему","careers":"учёный, программист, аналитик, врач-исследователь"},"storyteller":{"name":"Рассказчик","nameF":"Рассказчик","tagline":"Мыслит словами и историями, легко увлекает других","careers":"журналист, писатель, юрист, актёр"},"artist":{"name":"Художник","nameF":"Художник","tagline":"Замечает красоту и детали, создаёт своё","careers":"дизайнер, иллюстратор, музыкант, архитектор"},"explorer":{"name":"Исследователь","nameF":"Исследователь","tagline":"Наблюдает, собирает факты и идёт смотреть, что за углом","careers":"биолог, ветеринар, географ, эколог"},"leader":{"name":"Лидер","nameF":"Лидер","tagline":"Берёт инициативу, договаривается и ведёт за собой","careers":"предприниматель, менеджер, организатор, тренер"},"helper":{"name":"Помощник","nameF":"Помощник","tagline":"Чувствует других и первым приходит на помощь","careers":"врач, учитель, психолог, ветеринар"},"mover":{"name":"Непоседа","nameF":"Непоседа","tagline":"Думает в движении: сначала попробует телом, потом объяснит","careers":"спортсмен, тренер, хореограф, спасатель"}},"shade":{"swift":{"m":"быстрый","f":"быстрый"},"calm":{"m":"вдумчивый","f":"вдумчивый"}},"disclaimer":"Основано на наблюдениях родителя. Это не психологическая и не медицинская оценка.","report":{"builder":{"about":"{name} думает руками. Ему проще понять вещь, когда он её собрал, разобрал или построил сам. Он видит, как из частей получается целое, и не успокаивается, пока конструкция не встанет ровно.","hooks":"Затягивает: задачи с понятным результатом, который можно потрогать. Быстро надоедает: долгие объяснения без дела и занятия, где «нечего строить».","strengths":["Пространственное мышление: представляет, как детали сойдутся","Терпение в работе шаг за шагом","Доводит до работающего результата"],"grow":"Чему стоит помочь: объяснять словами, что и зачем он делает. Просите рассказать о постройке, как экскурсовода.","say":["«Расскажи, как ты это придумал»","«Что было самым трудным в этой постройке?»","«Что ты изменишь в следующий раз?»"],"ages":{"3-5":"крупный конструктор, песок и вода, постройки из коробок","6-8":"конструкторы с инструкцией, оригами, простые модели, робототехника для начинающих","9-12":"моделирование, 3D-ручка или 3D-редактор, столярная или техническая мастерская"},"plan":["Неделя 1. Постройка по образцу: одна модель по инструкции от начала до конца.","Неделя 2. Своя версия: изменить модель так, чтобы она стала лучше.","Неделя 3. Задача с ограничением: мост из бумаги, который выдержит книгу.","Неделя 4. Проект для семьи: сделать полезную вещь для дома и показать её."]},"inventor":{"about":"{name} хочет знать, как всё устроено, и проверяет это сам. Готовый ответ ему менее интересен, чем собственный опыт. Он пробует, ошибается и пробует иначе.","hooks":"Затягивает: загадки, опыты, вопрос «а что будет, если…». Быстро надоедает: повторять одно и то же и делать «потому что так надо».","strengths":["Любопытство и умение задавать точные вопросы","Логика: видит причину и следствие","Не боится ошибок, ищет другой способ"],"grow":"Чему стоит помочь: заканчивать начатое. Идей у него больше, чем доведённых дел. Договаривайтесь об одном маленьком финише.","say":["«Как ты это проверишь?»","«Отличный вопрос, давай узнаем вместе»","«Ошибка тоже результат. Что она показала?»"],"ages":{"3-5":"игры с водой и большие магниты для холодильника, сортировка, простые головоломки","6-8":"наборы юного учёного, шахматы, логические игры, первые шаги в программировании","9-12":"программирование, электроника, научный кружок, олимпиадные задачи"},"plan":["Неделя 1. Один опыт в день на 10 минут: что тонет, что притягивается, что растворяется.","Неделя 2. Дневник «я думал, а оказалось»: предположение до опыта и результат после.","Неделя 3. Логика: одна игра или головоломка, сложность растёт каждый день.","Неделя 4. Свой эксперимент: придумать вопрос, проверить и показать семье."]},"storyteller":{"about":"{name} мыслит словами и историями. Он запоминает то, что рассказано как сюжет, и сам превращает обычный день в рассказ. Ему важно, чтобы его слушали.","hooks":"Затягивает: книги, разговоры, роли, выступления. Быстро надоедает: молчаливая работа в одиночку и задания без смысла и героя.","strengths":["Богатая речь и память на истории","Воображение: придумывает миры и персонажей","Умеет увлечь и убедить"],"grow":"Чему стоит помочь: слушать других так же охотно, как говорить. Играйте в «интервью», где он задаёт вопросы.","say":["«Расскажи, что было дальше»","«Мне нравится, какое слово ты подобрал»","«А что чувствовал герой?»"],"ages":{"3-5":"чтение вслух с вопросами, кукольный театр, сочинение сказок перед сном","6-8":"театральная студия, свой комикс или книжка, иностранный язык","9-12":"дебаты, школьная газета или блог, литературный или театральный кружок"},"plan":["Неделя 1. История дня: каждый вечер три предложения о главном событии.","Неделя 2. Своя книжка: 6 страниц с рисунками и текстом.","Неделя 3. Интервью: расспросить бабушку, соседа или друга и пересказать.","Неделя 4. Выступление: показать историю семье, с ролями или куклами."]},"artist":{"about":"{name} замечает то, что другие пропускают: цвет, форму, звук, настроение. Он думает образами и хочет делать по-своему, а не как в образце.","hooks":"Затягивает: свобода выбрать материал и результат. Быстро надоедает: раскраски «по номерам», спешка и оценка «правильно или неправильно».","strengths":["Наблюдательность и чувство деталей","Оригинальные идеи","Способен надолго погрузиться в своё дело"],"grow":"Чему стоит помочь: показывать работу другим и спокойно принимать замечания. Начните с вопроса «что тебе самому здесь нравится?».","say":["«Расскажи, что здесь происходит»","«Я вижу, сколько труда ты вложил в эти детали»","«Как ты выбрал эти цвета?»"],"ages":{"3-5":"краски и пальчиковое рисование, лепка, музыка и танцы под неё","6-8":"художественная студия, музыкальный инструмент, поделки из подручного","9-12":"рисунок или цифровая иллюстрация, фото и видео, музыкальная группа или хор"},"plan":["Неделя 1. Один материал в день: карандаш, краски, пластилин, бумага, природные материалы.","Неделя 2. Одна тема, пять способов: нарисовать, слепить, сфотографировать, склеить, сыграть.","Неделя 3. Большая работа: один проект на всю неделю, по 15 минут в день.","Неделя 4. Домашняя выставка: выбрать лучшие работы, подписать и пригласить семью."]},"explorer":{"about":"{name} сначала смотрит, потом действует. Он собирает факты, замечает закономерности и помнит удивительные подробности о животных, планетах или динозаврах.","hooks":"Затягивает: всё новое, живое и настоящее, коллекции и карты. Быстро надоедает: сидеть в четырёх стенах и учить то, что нельзя увидеть.","strengths":["Наблюдательность","Память на факты и подробности","Самостоятельность: умеет занять себя"],"grow":"Чему стоит помочь: входить в новую компанию. Ему нужно время, чтобы осмотреться. Не торопите, дайте 10 минут понаблюдать.","say":["«Что ты сегодня заметил нового?»","«Покажи, что ты нашёл»","«Давай проверим, так ли это»"],"ages":{"3-5":"прогулки с лупой, уход за растением, книги о животных","6-8":"кружок юных натуралистов, коллекции, скауты, походы","9-12":"биология или астрономия, ориентирование, волонтёрство в приюте для животных"},"plan":["Неделя 1. Прогулка-исследование: каждый день найти три новые вещи на знакомом маршруте.","Неделя 2. Коллекция: собрать, разложить и подписать 10 находок.","Неделя 3. Наблюдение: неделя с одним объектом (растение, птицы, погода) и запись каждый день.","Неделя 4. Экспедиция: спланировать семейную вылазку и быть в ней проводником."]},"leader":{"about":"{name} быстро понимает, что нужно сделать, и собирает для этого людей. Он предлагает правила, распределяет роли и переживает за общий результат.","hooks":"Затягивает: цель, команда и возможность решать. Быстро надоедает: задания без выбора и ситуации, где от него ничего не зависит.","strengths":["Инициатива: начинает первым","Умеет договариваться","Берёт ответственность за результат"],"grow":"Чему стоит помочь: уступать и проигрывать. Давайте иногда роль «помощника капитана», где главный другой.","say":["«Как ты решил, кто что делает?»","«Что думают остальные? Спроси их»","«Сегодня ты отвечаешь за это сам»"],"ages":{"3-5":"игры с правилами, «дежурный по дому», простые командные игры","6-8":"командный спорт, настольные стратегии, скауты","9-12":"капитан команды, школьное самоуправление, свой маленький проект или ярмарка"},"plan":["Неделя 1. Одно своё дело дома: отвечает за него сам всю неделю.","Неделя 2. Семейная игра: объясняет правила и ведёт игру.","Неделя 3. Мини-проект: организовать прогулку или праздник для двух-трёх человек.","Неделя 4. Смена ролей: неделя, когда он помогает и следует чужому плану."]},"helper":{"about":"{name} считывает настроение людей раньше, чем они что-то скажут. Ему важны отношения: он помнит, кто что любит, и старается, чтобы всем было хорошо.","hooks":"Затягивает: дела вместе с кем-то и для кого-то. Быстро надоедает: соперничество и занятия, где каждый сам за себя.","strengths":["Эмпатия: понимает чувства других","Надёжность и забота","Умеет мирить и объединять"],"grow":"Чему стоит помочь: говорить «нет» и называть свои желания. Спрашивайте чаще «а чего хочешь ты?».","say":["«Ты заметил, что ему грустно. Это ценно»","«А чего хочется тебе?»","«Можно отказаться, и ты останешься хорошим другом»"],"ages":{"3-5":"ролевые игры в доктора и семью, уход за питомцем или растением, помощь на кухне","6-8":"кружки в маленьких группах, уход за животными, первая помощь для детей","9-12":"волонтёрство, наставник для младших, психология или биология"},"plan":["Неделя 1. Одно доброе дело в день и короткий разговор вечером, как это было.","Неделя 2. Забота о живом: поливать растение или кормить питомца становится ежедневным делом ребёнка, вы проверяете.","Неделя 3. Мои желания: каждый день один выбор делает только он (ужин, игра, маршрут).","Неделя 4. Подарок своими руками: придумать и сделать для близкого человека."]},"mover":{"about":"{name} думает в движении. Ему легче понять и запомнить, когда тело участвует: показать, попробовать, повторить. Энергии у него больше, чем требует обычный день.","hooks":"Затягивает: скорость, вызов, новые трюки. Быстро надоедает: долго сидеть и слушать без возможности встать.","strengths":["Координация и ловкость","Смелость пробовать новое","Упорство в тренировке навыка"],"grow":"Чему стоит помочь: спокойным занятиям. Давайте подвигаться перед ними: 10 минут активности помогают потом усидеть.","say":["«Покажи, как ты это делаешь»","«Вижу, сколько раз ты пробовал, прежде чем получилось»","«Сначала побегай, потом сядем»"],"ages":{"3-5":"беговел, полоса препятствий дома, плавание, танцы","6-8":"гимнастика, плавание, командные игры, единоборства","9-12":"секция по выбранному виду спорта, скалодром, танцевальная команда"},"plan":["Неделя 1. 10 минут движения каждый день: одна новая игра или упражнение.","Неделя 2. Один навык: выбрать трюк (скакалка, стойка, мяч) и тренировать всю неделю.","Неделя 3. Проба: одно пробное занятие в новой секции.","Неделя 4. Повторный замер: пройти тест движений и сравнить с первым результатом."],"extra":"Для этого типа в отчёте есть кнопка «Проверить физические сильные стороны»: 3 минуты упражнений перед камерой телефона."}},"cards":[{"id":"builder-1","scale":"builder","title":"Мост из бумаги","task":{"3-5":"Положите лист бумаги между двумя книгами. Сколько игрушек он выдержит? Сложите лист гармошкой и проверьте ещё раз.","6-8":"Постройте мост из одного листа бумаги между двумя книгами. Задача: чтобы он выдержал 10 монет. Скотч и ножницы нельзя.","9-12":"Три листа бумаги и скотч. Постройте мост длиной 30 см, который выдержит книгу. Сначала нарисуйте план, потом сравните с тем, что получилось."},"why":"Ребёнок на деле видит, что форма делает слабый материал прочным. Это основа инженерного мышления.","tip":"Не подсказывайте решение. Спросите: «Как думаешь, почему провисло? Что можно изменить?»","need":{"3-5":"лист бумаги, две книги, 5–6 лёгких игрушек","6-8":"лист бумаги, две книги, 10 монет или ластиков","9-12":"три листа бумаги, скотч, линейка, книга"},"steps":{"3-5":["Положите книги рядом, на расстоянии ладони взрослого, и накройте лист сверху как мост.","Ставьте игрушки на мост по одной и считайте вслух, сколько выдержит.","Сложите лист гармошкой вместе с ребёнком и положите снова.","Проверьте ещё раз и сравните: сколько игрушек было и сколько стало."],"6-8":["Задача: мост из одного листа должен выдержать 10 монет. Скотч и ножницы нельзя.","Первая попытка: ребёнок кладёт лист как есть и проверяет.","Дайте 3 минуты на поиски: можно гнуть, складывать, сворачивать.","Проверьте лучший вариант и попросите объяснить, почему он держит."],"9-12":["Условие: мост длиной 30 см должен выдержать книгу.","Сначала ребёнок рисует план: какая форма, где опоры.","Сборка по плану, 5 минут.","Испытание книгой. Сравните план и результат: что пришлось менять и почему."]}},{"id":"builder-2","scale":"builder","title":"Самая высокая башня","task":{"3-5":"Постройте башню из кубиков или пластиковых стаканов выше, чем колено ребёнка. Потом выше пояса.","6-8":"У вас 20 предметов из кухни (стаканчики, губки, коробки). Постройте башню выше стола. Упала? Найдите, какой этаж подвёл.","9-12":"Башня только из бумаги и скотча, без опоры на стену. Цель: 1 метр. Замерьте, запишите рекорд, попробуйте побить."},"why":"Башня учит равновесию, терпению и поиску ошибки: упало не «всё», а подвёл один этаж.","tip":"Когда башня падает, не утешайте сразу. Спросите: «Какой этаж подвёл?»","need":{"3-5":"кубики или пластиковые стаканы","6-8":"20 предметов из кухни: стаканчики, губки, коробки","9-12":"бумага, скотч, рулетка"},"steps":{"3-5":["Постройте вместе башню выше колена ребёнка.","Теперь цель выше: до пояса. Строит ребёнок, вы подаёте.","Если упала, посмотрите вместе, где она качнулась.","Постройте ещё раз с широким низом и сравните."],"6-8":["Разложите предметы и дайте минуту их рассмотреть.","Задача: башня выше стола. Строит ребёнок.","Упала? Найдите этаж, который подвёл, и замените его.","Измерьте готовую башню ладонями и запомните рекорд."],"9-12":["Условие: башня только из бумаги и скотча, без опоры на стену. Цель: 1 метр.","Ребёнок выбирает форму опор: трубки, треугольники или гармошка.","Сборка 7 минут, потом замер.","Запишите рекорд и одну идею, как его побить в следующий раз."]}},{"id":"builder-3","scale":"builder","title":"Домик для игрушки","task":{"3-5":"Сделайте из коробки и подушек домик для любимой игрушки. Где дверь? Где кровать?","6-8":"Постройте из коробки дом для игрушки: дверь, которая открывается, и окно. Ножницами работает взрослый.","9-12":"Спроектируйте дом из коробки: сначала чертёж с размерами, потом сборка. В доме должно быть два этажа и лестница."},"why":"Ребёнок планирует пространство: что где стоит и зачем. Так появляется привычка сначала думать, потом строить.","tip":"Задавайте вопросы от имени игрушки: «А где я буду спать? Как я войду?»","need":{"3-5":"коробка, подушки, любимая игрушка","6-8":"коробка, фломастеры, скотч, ножницы (режет взрослый)","9-12":"коробка, линейка, бумага, скотч, ножницы"},"steps":{"3-5":["Спросите: какой дом нужен игрушке? Большой или маленький?","Постройте стены из подушек и коробки.","Найдите вместе, где дверь и где кровать.","Заселите игрушку и пожелайте ей спокойной ночи."],"6-8":["Ребёнок отмечает фломастером, где будут дверь и окно.","Взрослый вырезает по линиям, дверь оставляет на одной стороне, чтобы открывалась.","Ребёнок оформляет дом: стены, коврик, мебель из мелких коробочек.","Экскурсия по дому: ребёнок показывает и рассказывает."],"9-12":["Сначала чертёж: два этажа и лестница, размеры в сантиметрах.","Ребёнок размечает детали по линейке.","Сборка. Острые и тугие места режет взрослый.","Сверьте дом с чертежом: что совпало, что пришлось изменить."]}},{"id":"builder-4","scale":"builder","title":"Горка для шарика","task":{"3-5":"Сделайте горку из картона или книги. Катайте мячик. Что едет быстрее: мячик или машинка?","6-8":"Соберите трассу для шарика из картонных трубок и скотча на стене или двери. Шарик должен ехать не меньше 5 секунд.","9-12":"Трасса для шарика с тремя поворотами и финишем в стакане. Засеките время. Задача: сделать спуск медленнее, не останавливая шарик."},"why":"Опыт с наклоном и скоростью: ребёнок сам меняет условие и сразу видит результат.","tip":"Перед каждым запуском просите прогноз: «Как думаешь, что будет быстрее?»","need":{"3-5":"картонка или большая книга, мячик, машинка","6-8":"картонные трубки от рулонов, бумажный скотч, мячик или шарик из фольги","9-12":"трубки, картон, скотч, стакан, секундомер"},"steps":{"3-5":["Сделайте горку: один край картонки положите на диван или стопку книг.","Скатите мячик, потом машинку. Что приехало быстрее?","Поднимите край выше и проверьте ещё раз.","Пусть ребёнок сам выберет, что скатить третьим."],"6-8":["Приклейте первую трубку к двери или стене под наклоном.","Ребёнок добавляет следующие, чтобы шарик переходил из одной в другую.","Запускайте после каждой новой детали и поправляйте.","Цель: шарик едет не меньше 5 секунд. Считайте вслух."],"9-12":["Условие: три поворота и финиш в стакане.","Ребёнок собирает трассу и делает пробный запуск.","Замер времени. Новая задача: сделать спуск медленнее, но чтобы шарик не останавливался.","Запишите время до и после и что именно изменили."]}},{"id":"builder-5","scale":"builder","title":"Почини вместе со мной","task":{"3-5":"Дайте ребёнку закрутить большую крышку, застегнуть молнию или липучку. Пусть сделает сам до конца.","6-8":"Найдите дома вещь, которую надо подтянуть или склеить. Ребёнок делает, вы только подсказываете.","9-12":"Выберите вместе небольшую домашнюю поломку. Ребёнок сам выясняет причину, предлагает способ и чинит. Вы отвечаете за безопасность."},"why":"Ребёнок чувствует, что его руки могут починить настоящую вещь. Это даёт уверенность сильнее любой похвалы.","tip":"Руки держите за спиной. Помогайте словами, а не делом.","need":{"3-5":"банка с большой крышкой, куртка с молнией, обувь на липучке","6-8":"вещь, которую надо подтянуть или склеить, отвёртка или клей","9-12":"небольшая домашняя поломка, нужные инструменты"},"steps":{"3-5":["Покажите один раз медленно, как закручивается крышка.","Ребёнок закручивает сам до конца.","То же с молнией и липучкой.","Скажите, что именно получилось: «Ты сам застегнул до самого верха»."],"6-8":["Найдите вместе, что дома разболталось или отклеилось.","Ребёнок осматривает и говорит, что с вещью не так.","Чинит ребёнок, вы только подсказываете.","Проверьте вместе: держится?"],"9-12":["Выберите вместе одну поломку: скрипит дверца, шатается ручка.","Ребёнок выясняет причину и предлагает способ.","Вы проверяете, что это безопасно, и ребёнок чинит.","Через день проверьте, держится ли ремонт."]}},{"id":"inventor-1","scale":"inventor","title":"Тонет или плавает","task":{"3-5":"Таз с водой и 6 крупных предметов. Перед каждым спросите: утонет или поплывёт? Потом проверьте. Будьте рядом и вылейте воду сразу после игры.","6-8":"10 предметов. Ребёнок записывает прогноз для каждого, потом проверяет. Сколько угадал? Что общего у тех, что плавают?","9-12":"Сделайте из фольги лодку, которая выдержит больше всего монет. Три попытки с разной формой. Какая форма выиграла и почему?"},"why":"Прогноз, опыт, вывод: ребёнок проходит путь учёного в миниатюре.","tip":"Если прогноз не сбылся, порадуйтесь: «Вот это неожиданно! Почему так вышло?»","need":{"3-5":"таз с водой, 6 крупных предметов: губка, ложка, пластиковая крышка, яблоко, мяч, деревянный кубик","6-8":"таз с водой, 10 предметов, лист и карандаш","9-12":"фольга, таз с водой, монеты"},"steps":{"3-5":["Перед каждым предметом спросите: утонет или поплывёт?","Ребёнок опускает предмет в воду сам.","Разложите на две стороны: что плавает и что тонет.","Будьте рядом всё время. После игры сразу вылейте воду."],"6-8":["Ребёнок записывает или рисует прогноз для каждого предмета.","Проверяет по одному и ставит плюс или минус.","Посчитайте, сколько прогнозов сбылось.","Спросите: что общего у тех, что плавают?"],"9-12":["Задача: лодка из фольги, которая выдержит больше всего монет.","Три попытки с разной формой: плоская, с бортами, длинная.","Для каждой считайте монеты до затопления.","Какая форма выиграла и почему? Запишите ответ одной фразой."]}},{"id":"inventor-2","scale":"inventor","title":"Что будет, если","task":{"3-5":"Смешайте воду с тем, что есть на кухне: соль, сахар, мука, масло. Что исчезло, а что нет? Пробовать на вкус ничего не нужно.","6-8":"Сода и уксус в стакане. Сначала прогноз, потом опыт. Что изменится, если соды взять вдвое больше?","9-12":"Придумайте свой вопрос «что будет, если…» про воду, лёд или магнит. Запишите прогноз, проведите опыт, запишите результат."},"why":"Ребёнок учится менять одно условие и смотреть, что изменилось. Так устроен любой эксперимент.","tip":"Вместо объяснений задавайте вопрос: «А если взять больше? А если теплее?»","need":{"3-5":"4 стакана воды, ложка, соль, сахар, мука, растительное масло","6-8":"стакан, поднос, сода, уксус, ложка","9-12":"вода, лёд или магнит на выбор, лист для записей"},"steps":{"3-5":["В каждый стакан ребёнок добавляет ложку одного продукта.","Размешайте и посмотрите: что исчезло, а что нет?","Найдите стакан, где получилось самое интересное.","Пробовать на вкус ничего не нужно. После опыта вылейте всё вместе."],"6-8":["Поставьте стакан на поднос. Ребёнок говорит прогноз: что будет?","Насыпьте ложку соды, уксус наливает взрослый.","Повторите с двумя ложками соды.","Что изменилось? Ребёнок объясняет своими словами."],"9-12":["Ребёнок придумывает свой вопрос «что будет, если…».","Записывает прогноз.","Проводит опыт. Вы следите за безопасностью.","Записывает результат и сравнивает с прогнозом."]}},{"id":"inventor-3","scale":"inventor","title":"Новая жизнь вещи","task":{"3-5":"Возьмите пустую коробку. Чем она может быть? Придумайте три варианта и поиграйте в каждый.","6-8":"Одна прищепка. Придумайте 10 способов её использовать, кроме сушки белья. Лучший проверьте на деле.","9-12":"Выберите вещь, которую собирались выбросить. Придумайте из неё полезный предмет для дома и сделайте его."},"why":"Привычка видеть в обычной вещи много возможностей. С неё начинается изобретательность.","tip":"Принимайте все идеи, даже странные. Отбирать будете потом.","need":{"3-5":"пустая коробка","6-8":"одна прищепка, лист бумаги","9-12":"вещь, которую собирались выбросить, клей, скотч, ножницы"},"steps":{"3-5":["Спросите: чем может быть эта коробка?","Придумайте три варианта: машина, домик, шляпа.","Поиграйте в каждый по минуте.","Какой вариант понравился больше всего?"],"6-8":["Задача: 10 способов использовать прищепку, кроме сушки белья.","Ребёнок называет, вы записываете. Первые идеи будут простыми, дальше интереснее.","Выберите вместе лучшую.","Проверьте её на деле."],"9-12":["Выберите вещь: банка, коробка, старая футболка.","Ребёнок придумывает, каким полезным предметом для дома она станет.","Делает его. Вы помогаете только там, где нужен инструмент.","Найдите предмету место и пользуйтесь неделю."]}},{"id":"inventor-4","scale":"inventor","title":"Найди закономерность","task":{"3-5":"Выложите ряд: ложка, вилка, ложка, вилка. Что дальше? Потом ряд придумывает ребёнок.","6-8":"Напишите ряд чисел: 2, 4, 6, 8. Что дальше? Затем 1, 2, 4, 7, 11. Потом ребёнок загадывает ряд вам.","9-12":"Ребёнок придумывает шифр (буква = число или значок) и пишет вам записку. Ваша задача: расшифровать. Потом меняетесь."},"why":"Умение замечать правило в ряду нужно в математике, музыке и программировании.","tip":"Когда ребёнок загадывает ряд вам, ошибитесь один раз нарочно. Пусть объяснит правило.","need":{"3-5":"4 ложки и 4 вилки (или кубики двух цветов)","6-8":"лист бумаги, карандаш","9-12":"бумага, ручка"},"steps":{"3-5":["Выложите ряд: ложка, вилка, ложка, вилка.","Спросите: что дальше? Ребёнок кладёт следующий предмет.","Усложните: две ложки, одна вилка.","Теперь ряд придумывает ребёнок, а продолжаете вы."],"6-8":["Напишите ряд: 2, 4, 6, 8. Что дальше?","Затем ряд сложнее: 1, 2, 4, 7, 11.","Попросите объяснить правило словами.","Ребёнок загадывает свой ряд вам."],"9-12":["Ребёнок придумывает шифр: буква равна числу или значку.","Пишет вам записку из одного предложения.","Вы расшифровываете. Ключ дайте только после трёх попыток.","Поменяйтесь ролями."]}},{"id":"inventor-5","scale":"inventor","title":"Машина для простого дела","task":{"3-5":"Как достать игрушку с полки, не вставая? Попробуйте верёвку, ложку, палку. Что сработало?","6-8":"Придумайте и нарисуйте машину, которая кормит кота или поливает цветок. Подпишите, что делает каждая часть.","9-12":"Соберите цепочку из 4 шагов: домино толкает шарик, шарик падает в стакан и так далее. Цель: в конце звенит колокольчик или падает ложка."},"why":"Ребёнок разбивает задачу на шаги и соединяет их в цепочку. Это инженерное и логическое мышление вместе.","tip":"Не исправляйте конструкцию сами. Спросите: «На каком шаге остановилось?»","need":{"3-5":"игрушка на невысокой полке, верёвка, большая ложка, палка","6-8":"лист бумаги, карандаши","9-12":"домино, шарик, стакан, книги, ложка или колокольчик"},"steps":{"3-5":["Задача: достать игрушку, не вставая с пола.","Попробуйте по очереди верёвку, ложку и палку.","Что сработало лучше всего?","Придумайте вместе ещё один способ."],"6-8":["Задача: придумать машину, которая кормит кота или поливает цветок.","Ребёнок рисует её целиком.","Подписывает, что делает каждая часть.","Рассказывает вам, как она работает, от начала до конца."],"9-12":["Задача: цепочка из 4 шагов, в конце звенит колокольчик или падает ложка.","Ребёнок собирает и проверяет каждый шаг отдельно.","Запуск целиком. Не получилось? Найдите шаг, где остановилось.","Снимите удачный запуск на телефон."]}},{"id":"storyteller-1","scale":"storyteller","title":"История из трёх вещей","task":{"3-5":"Возьмите три игрушки. Начните: «Жил-был…». Ребёнок говорит, что случилось дальше.","6-8":"Три случайных предмета из комнаты. Ребёнок сочиняет историю, где все три важны. У истории есть начало, беда и конец.","9-12":"Три случайных слова из книги. Ребёнок за 10 минут пишет историю на полстраницы с неожиданным концом и читает её вслух."},"why":"Ребёнок строит сюжет: начало, трудность, развязка. Это основа связной речи и письма.","tip":"Не поправляйте сюжет. Помогайте вопросом: «И что случилось потом?»","need":{"3-5":"три игрушки","6-8":"три случайных предмета из комнаты","9-12":"книга, лист бумаги, ручка, таймер"},"steps":{"3-5":["Поставьте три игрушки перед ребёнком.","Начните: «Жил-был…» и назовите первую игрушку.","Ребёнок говорит, что случилось дальше. Вы добавляете по одной фразе по очереди.","Закончите вместе: чем всё кончилось?"],"6-8":["Ребёнок с закрытыми глазами выбирает три предмета.","Условие: в истории важны все три.","У истории есть начало, беда и конец. Ребёнок рассказывает вслух.","Перескажите историю ему в двух фразах: так ли вы поняли?"],"9-12":["Откройте книгу наугад три раза и выпишите по одному слову.","За 10 минут ребёнок пишет историю на полстраницы с этими словами.","Условие: неожиданный конец.","Ребёнок читает вслух. Скажите, в каком месте вам стало интересно."]}},{"id":"storyteller-2","scale":"storyteller","title":"Другой конец","task":{"3-5":"Прочитайте знакомую сказку и остановитесь перед концом. Спросите: а как ещё могло закончиться?","6-8":"Ребёнок пересказывает любимую сказку, но злодей оказывается добрым. Что меняется?","9-12":"Ребёнок пересказывает известную историю от лица второстепенного героя. Что тот видел и чего не знал?"},"why":"Менять известный сюжет значит понимать, как он устроен. Так развивается гибкость мышления.","tip":"Спрашивайте «почему он так поступил?», а не «правильно ли это?».","need":{"3-5":"знакомая книжка со сказкой","6-8":"ничего не нужно","9-12":"ничего не нужно"},"steps":{"3-5":["Читайте сказку и остановитесь перед самым концом.","Спросите: а как ещё могло закончиться?","Примите любой вариант и продолжите его одной фразой.","Дочитайте настоящий конец. Какой нравится больше?"],"6-8":["Ребёнок выбирает любимую сказку.","Условие: злодей на самом деле добрый.","Ребёнок пересказывает сказку с этим изменением.","Обсудите: что поменялось для остальных героев?"],"9-12":["Выберите известную историю, книгу или фильм.","Ребёнок выбирает второстепенного героя.","Пересказывает события от его лица: что тот видел и чего не знал.","Спросите: кто в этой версии главный герой?"]}},{"id":"storyteller-3","scale":"storyteller","title":"Интервью","task":{"3-5":"Ребёнок с «микрофоном» (ложкой) спрашивает вас: что ты любил, когда был маленьким?","6-8":"Ребёнок готовит 5 вопросов бабушке, дедушке или вам про детство и берёт интервью. Потом рассказывает, что удивило.","9-12":"Ребёнок берёт интервью у взрослого о его профессии: 7 вопросов, без «да/нет». Потом пересказывает главное за одну минуту."},"why":"Ребёнок учится задавать вопросы и слушать ответ. Это половина умения разговаривать.","tip":"Отвечайте всерьёз и коротко. Интервью ведёт ребёнок, а не вы.","need":{"3-5":"большая ложка вместо микрофона","6-8":"лист бумаги, карандаш, бабушка, дедушка или вы","9-12":"блокнот, ручка, взрослый с интересной работой"},"steps":{"3-5":["Дайте ребёнку «микрофон».","Он спрашивает: что ты любил делать, когда был маленьким?","Ответьте одной короткой историей.","Поменяйтесь: теперь вопрос задаёте вы."],"6-8":["Ребёнок готовит 5 вопросов про детство.","Берёт интервью лично или по телефону.","Можно рисовать или записывать главное.","Потом рассказывает вам, что удивило больше всего."],"9-12":["Ребёнок готовит 7 вопросов о профессии. Условие: на них нельзя ответить «да» или «нет».","Проводит интервью и делает пометки.","За одну минуту пересказывает вам главное.","Спросите: какой вопрос оказался самым удачным?"]}},{"id":"storyteller-4","scale":"storyteller","title":"Новые слова","task":{"3-5":"Придумайте вместе смешное имя для каждой игрушки и объясните, почему её так зовут.","6-8":"Придумайте слово, которого нет, и что оно значит. Используйте его сегодня три раза в разговоре.","9-12":"Выберите в книге три незнакомых слова. Ребёнок сначала угадывает значение по тексту, потом проверяет и составляет с каждым фразу."},"why":"Игра со словами расширяет словарь и показывает, что язык можно придумывать, а не только учить.","tip":"Используйте новое слово сами. Ребёнку важно услышать его в вашей речи.","need":{"3-5":"3–4 игрушки","6-8":"ничего не нужно","9-12":"книга, лист бумаги"},"steps":{"3-5":["Возьмите первую игрушку и придумайте ей смешное имя.","Ребёнок объясняет, почему её так зовут.","Следующей игрушке имя придумывает ребёнок.","Познакомьте игрушки друг с другом по новым именам."],"6-8":["Придумайте вместе слово, которого нет.","Договоритесь, что оно значит.","Задача на день: использовать его три раза в разговоре.","Вечером посчитайте, кто сколько раз вспомнил."],"9-12":["Ребёнок находит в книге три незнакомых слова.","Сначала угадывает значение по соседним фразам.","Проверяет по словарю или у вас.","Составляет с каждым словом свою фразу."]}},{"id":"storyteller-5","scale":"storyteller","title":"Репортаж с места","task":{"3-5":"Ребёнок рассказывает, что видит в окне, как диктор: «Вот едет красная машина…»","6-8":"Ребёнок ведёт минутный репортаж с ужина или прогулки: кто, что, где. Можно записать на телефон и послушать.","9-12":"Ребёнок готовит двухминутный выпуск новостей семьи за неделю: три новости, прогноз на выходные. Запишите и покажите родным."},"why":"Ребёнок описывает то, что видит, по порядку и понятно для слушателя. Это навык выступления.","tip":"Будьте зрителем: слушайте до конца и задайте один вопрос «из студии».","need":{"3-5":"окно","6-8":"телефон для записи (по желанию)","9-12":"лист бумаги, телефон для записи"},"steps":{"3-5":["Сядьте у окна вместе.","Покажите пример голосом диктора: «Вот едет красная машина…»","Теперь репортаж ведёт ребёнок, одну минуту.","Поблагодарите «корреспондента» и спросите, что было самым интересным."],"6-8":["Тема: ужин или прогулка.","Ребёнок минуту рассказывает: кто, что, где.","Запишите на телефон.","Послушайте вместе. Что он добавил бы в следующий раз?"],"9-12":["Ребёнок выбирает три новости семьи за неделю.","Добавляет прогноз на выходные.","Записывает двухминутный выпуск.","Покажите запись родным."]}},{"id":"artist-1","scale":"artist","title":"Рисунок из кляксы","task":{"3-5":"Нарисуйте каракулю. Ребёнок превращает её в зверя: добавляет глаза, лапы, хвост.","6-8":"Каждый рисует каракулю и отдаёт другому. Задача: превратить чужую каракулю в картинку и дать ей название.","9-12":"Пять случайных линий на листе. Ребёнок делает из них законченный рисунок, где ни одна линия не лишняя."},"why":"Ребёнок учится видеть образ в случайной форме. Так работает воображение художника и дизайнера.","tip":"Спрашивайте «что ты здесь увидел?», а не «что это?».","need":{"3-5":"лист бумаги, толстые фломастеры или мелки","6-8":"два листа, фломастеры","9-12":"лист бумаги, карандаш или ручка"},"steps":{"3-5":["Нарисуйте на листе одну каракулю.","Спросите: на кого она похожа?","Ребёнок добавляет глаза, лапы, хвост.","Придумайте зверю имя."],"6-8":["Каждый рисует каракулю на своём листе.","Поменяйтесь листами.","Задача: превратить чужую каракулю в картинку.","Дайте картинкам названия и покажите друг другу."],"9-12":["Нарисуйте на листе пять случайных линий.","Ребёнок делает из них законченный рисунок.","Условие: ни одна линия не лишняя.","Попросите показать, чем стала каждая линия."]}},{"id":"artist-2","scale":"artist","title":"Один цвет","task":{"3-5":"Назовите цвет. Соберите по дому всё такого цвета и выложите из находок картинку на полу.","6-8":"Нарисуйте картину только одним цветом и его оттенками. Как показать ночь, если у вас только синий?","9-12":"Сфотографируйте на телефон 7 предметов одного цвета так, чтобы снимки смотрелись как серия. Выберите лучший кадр и объясните почему."},"why":"Ограничение одним цветом заставляет искать оттенки и форму. Так тренируется глаз.","tip":"Обратите внимание на оттенки: «Смотри, этот синий темнее. Где он пригодится?»","need":{"3-5":"предметы одного цвета из дома","6-8":"лист бумаги, краски или карандаши одного цвета, вода","9-12":"телефон с камерой"},"steps":{"3-5":["Назовите цвет дня.","Соберите по дому всё такого цвета: игрушки, носки, крышки.","Выложите из находок картинку на полу.","Сфотографируйте её и разложите вещи по местам вместе."],"6-8":["Ребёнок выбирает один цвет.","Задача: нарисовать картину только им и его оттенками.","Спросите: как показать ночь, если есть только синий?","Найдите на рисунке самое светлое и самое тёмное место."],"9-12":["Ребёнок выбирает цвет.","Снимает 7 предметов этого цвета так, чтобы кадры смотрелись как серия.","Выбирает лучший кадр.","Объясняет, почему именно он."]}},{"id":"artist-3","scale":"artist","title":"Музыка на бумаге","task":{"3-5":"Включите быструю песню, потом медленную. Ребёнок рисует под каждую. Чем рисунки отличаются?","6-8":"Включите музыку без слов. Ребёнок рисует то, что слышит: линии, пятна, цвета. Потом рассказывает, где на рисунке громко.","9-12":"Два разных трека, два листа. Ребёнок передаёт настроение каждого только формой и цветом, без предметов. Вы угадываете, где какой."},"why":"Ребёнок переводит звук в линию и цвет. Это связывает слух, чувство и руку.","tip":"Не просите рисовать предметы. Здесь важны линии, пятна и настроение.","need":{"3-5":"два листа бумаги, мелки, две песни: быстрая и медленная","6-8":"лист бумаги, краски или фломастеры, музыка без слов","9-12":"два листа, краски или карандаши, два разных трека"},"steps":{"3-5":["Включите быструю песню. Ребёнок рисует под неё на первом листе.","Включите медленную. Второй лист.","Положите рисунки рядом.","Чем они отличаются? Покажите пальцем."],"6-8":["Включите музыку без слов.","Ребёнок рисует то, что слышит: линии, пятна, цвета.","После музыки спросите: где на рисунке громко, а где тихо?","Придумайте рисунку название."],"9-12":["Ребёнок слушает первый трек и передаёт настроение только формой и цветом, без предметов.","То же со вторым треком.","Вы угадываете, какой лист к какому треку.","Ребёнок объясняет свой выбор цвета."]}},{"id":"artist-4","scale":"artist","title":"Картина из находок","task":{"3-5":"Соберите на прогулке листья, палочки, шишки. Дома выложите из них лицо или зверя.","6-8":"Коллаж из старого журнала и находок с прогулки. Тема: «место, где я хочу оказаться».","9-12":"Соберите композицию из предметов на столе, как натюрморт. Подвигайте лампу: как меняется картина от света? Сфотографируйте лучший вариант."},"why":"Композиция из готовых предметов учит замечать форму, фактуру и то, как вещи сочетаются.","tip":"Спросите: «Что будет, если это передвинуть сюда?» и дайте попробовать.","need":{"3-5":"листья, палочки, шишки с прогулки, лист бумаги","6-8":"старый журнал, находки с прогулки, клей, лист бумаги, ножницы","9-12":"3–5 предметов, настольная лампа, телефон"},"steps":{"3-5":["Соберите на прогулке листья, палочки и шишки.","Дома разложите находки на столе.","Выложите вместе лицо или зверя.","Сфотографируйте. После игры вымойте руки."],"6-8":["Тема: место, где я хочу оказаться.","Ребёнок вырезает или вырывает картинки из журнала.","Сначала раскладывает на листе, потом клеит.","Рассказывает вам, что это за место."],"9-12":["Ребёнок собирает композицию из предметов на столе, как натюрморт.","Двигает лампу: сбоку, сверху, сзади.","Смотрит, как меняются тени и настроение.","Фотографирует лучший вариант."]}},{"id":"artist-5","scale":"artist","title":"Свой узор","task":{"3-5":"Печатайте краской пальцами, губкой или половинкой картофеля. Получится узор для открытки.","6-8":"Придумайте узор для своей футболки или кружки и нарисуйте его на бумаге в натуральную величину.","9-12":"Придумайте знак (логотип) для своей семьи: три наброска, один финальный. Объясните, что значит каждая деталь."},"why":"Повторяющийся узор учит ритму и аккуратности, а знак учит выражать идею коротко.","tip":"Повесьте готовую работу на видное место. Для ребёнка это значит больше слов.","need":{"3-5":"краска для пальчиков, губка, половинка картофеля, лист бумаги, клеёнка","6-8":"лист бумаги, фломастеры","9-12":"бумага, карандаш, фломастеры"},"steps":{"3-5":["Застелите стол клеёнкой.","Покажите отпечаток пальцем, губкой, картофелем.","Ребёнок печатает узор по всему листу.","Когда высохнет, сложите лист пополам: получится открытка."],"6-8":["Ребёнок выбирает: узор для футболки или для кружки.","Обводит на листе контур в натуральную величину.","Заполняет его узором.","Спросите: кому бы он подарил такую вещь?"],"9-12":["Задача: знак вашей семьи.","Три быстрых наброска, по минуте на каждый.","Ребёнок выбирает один и рисует финальный вариант.","Объясняет, что значит каждая деталь."]}},{"id":"explorer-1","scale":"explorer","title":"Охота за находками","task":{"3-5":"На прогулке найдите: что-то круглое, что-то мягкое, что-то жёлтое, что-то шумное.","6-8":"Список из 8 находок на прогулку: лист с зубчиками, след, что-то старше вас, что-то, чего вчера не было.","9-12":"Ребёнок сам составляет список из 10 находок для вас и ведёт маршрут. По дороге фотографирует самое странное, что заметит."},"why":"Поиск по признаку тренирует внимание и умение замечать детали вокруг.","tip":"Не показывайте находку сами. Сужайте круг: «Посмотри ниже. Теплее!»","need":{"3-5":"прогулка, пакет или ведёрко","6-8":"список из 8 находок на листке, карандаш","9-12":"листок, ручка, телефон с камерой"},"steps":{"3-5":["Назовите четыре задания: что-то круглое, что-то мягкое, что-то жёлтое, что-то шумное.","Ищите по одному. Ребёнок показывает находку.","Спросите про каждую: какая она на ощупь?","Дома вспомните все четыре находки."],"6-8":["Напишите список: лист с зубчиками, след, что-то старше вас, что-то, чего вчера не было, и ещё четыре своих.","На прогулке ребёнок ищет и вычёркивает.","Про спорные находки пусть докажет, что подходит.","Какая находка была самой трудной?"],"9-12":["Ребёнок сам составляет список из 10 находок для вас.","Ведёт маршрут, вы ищете.","По дороге он фотографирует самое странное, что заметит.","Дома посмотрите фото и выберите находку дня."]}},{"id":"explorer-2","scale":"explorer","title":"Карта комнаты","task":{"3-5":"Спрячьте игрушку и подсказывайте: «рядом с кроватью», «под столом». Потом прячет ребёнок.","6-8":"Ребёнок рисует карту комнаты сверху и отмечает крестиком спрятанный клад. Вы ищете по карте.","9-12":"Ребёнок рисует карту пути от дома до школы или магазина по памяти. Потом вы проходите маршрут и исправляете карту."},"why":"Карта учит представлять пространство сверху и переводить его на бумагу.","tip":"Ищите по карте честно. Если карта неточная, пусть ребёнок сам увидит, где сбой.","need":{"3-5":"любимая игрушка","6-8":"лист бумаги, карандаш, маленький «клад»","9-12":"лист бумаги, карандаш"},"steps":{"3-5":["Спрячьте игрушку в комнате, пока ребёнок не смотрит.","Подсказывайте словами: «рядом с кроватью», «под столом».","Нашёл? Теперь прячет он, а подсказки говорит вам.","Сыграйте три круга."],"6-8":["Ребёнок рисует комнату сверху: кровать, стол, дверь.","Прячет клад и ставит на карте крестик.","Вы ищете только по карте.","Поменяйтесь: карту рисуете вы."],"9-12":["Ребёнок по памяти рисует путь от дома до школы или магазина.","Отмечает повороты и три ориентира.","Пройдите маршрут вместе с картой в руках.","Исправьте на карте то, что не совпало."]}},{"id":"explorer-3","scale":"explorer","title":"Пять минут тишины","task":{"3-5":"Сядьте у окна на 2 минуты. Что вы слышите? Считайте звуки на пальцах.","6-8":"5 минут во дворе молча. Потом каждый называет три вещи, которые заметил, а другой нет.","9-12":"10 минут наблюдения за одним местом (кормушка, перекрёсток, муравейник). Ребёнок записывает, что происходит, и находит одну закономерность."},"why":"Тихое наблюдение учит замечать то, что обычно пропускаешь. Это главный инструмент исследователя.","tip":"Молчите вместе с ребёнком. Ваш пример работает лучше просьбы «сиди тихо».","need":{"3-5":"окно или скамейка","6-8":"двор или парк, таймер на 5 минут","9-12":"блокнот, ручка, место для наблюдения: кормушка, перекрёсток, муравейник"},"steps":{"3-5":["Сядьте рядом на 2 минуты.","Закройте глаза и слушайте.","Каждый новый звук считайте на пальцах.","Какой звук был самым тихим?"],"6-8":["Договоритесь: 5 минут молчим и смотрим.","Каждый запоминает то, что заметил.","Потом по очереди называйте по три вещи.","Побеждает тот, кто заметил то, чего не видел другой."],"9-12":["Ребёнок выбирает одно место и 10 минут наблюдает.","Записывает, что происходит и когда.","Ищет одну закономерность: что повторяется?","Рассказывает вам вывод и как его проверить завтра."]}},{"id":"explorer-4","scale":"explorer","title":"Моя коллекция","task":{"3-5":"Разложите большие крышки, носки или кубики по кучкам: по цвету, потом по размеру.","6-8":"Соберите 10 листьев или камней. Ребёнок сам решает, как их разделить на группы, и объясняет правило.","9-12":"Начните коллекцию на неделю: каждый день одна находка с подписью, где и когда найдена. В конце недели сделайте витрину."},"why":"Сортировка учит находить признак и объяснять правило. С этого начинается любая классификация.","tip":"Не подсказывайте правило. Спросите: «Почему эти вместе?»","need":{"3-5":"большие крышки, носки или кубики","6-8":"10 листьев или камней с прогулки","9-12":"коробка или полка, бумажки для подписей"},"steps":{"3-5":["Высыпьте предметы на пол.","Разложите вместе по цвету.","Смешайте и разложите по размеру: большие и маленькие.","Пусть ребёнок придумает третий способ."],"6-8":["Разложите находки на столе.","Ребёнок сам решает, как разделить их на группы.","Объясняет правило.","Попросите разделить ещё раз по другому правилу."],"9-12":["Ребёнок выбирает тему коллекции на неделю.","Каждый день одна находка с подписью: где и когда найдена.","В конце недели делает из них выставку.","Проводит для семьи экскурсию на две минуты."]}},{"id":"explorer-5","scale":"explorer","title":"Вопрос дня","task":{"3-5":"Ребёнок задаёт один вопрос «почему». Ищете ответ вместе: в книге, на улице или опытом.","6-8":"Ребёнок выбирает животное и находит о нём три факта, которых вы не знали. Проверьте, правда ли не знали.","9-12":"Ребёнок выбирает вопрос, на который нет быстрого ответа, находит два разных источника и рассказывает, в чём они расходятся."},"why":"Ребёнок учится искать ответ сам и проверять его. Это навык на всю учёбу.","tip":"Скажите честно «я не знаю, давай выясним». Это лучший пример для исследователя.","need":{"3-5":"детская энциклопедия или окно","6-8":"книга о животных или поиск вместе со взрослым","9-12":"два источника: книга и сайт или два сайта"},"steps":{"3-5":["Ребёнок задаёт один вопрос «почему».","Скажите: давай выясним вместе.","Ищите ответ в книге, на улице или простым опытом.","Попросите рассказать ответ другому взрослому."],"6-8":["Ребёнок выбирает животное.","Находит о нём три факта, которых вы не знали.","Рассказывает вам.","Честно скажите, какие из них вы правда не знали."],"9-12":["Ребёнок выбирает вопрос, на который нет быстрого ответа.","Находит два разных источника.","Сравнивает: в чём они сходятся и в чём расходятся?","Рассказывает, какому верит больше и почему."]}},{"id":"leader-1","scale":"leader","title":"Капитан на 15 минут","task":{"3-5":"15 минут ребёнок главный: выбирает игру и говорит, кто что делает. Вы слушаетесь.","6-8":"Ребёнок планирует семейную прогулку на час: куда идём, что берём, кто за что отвечает.","9-12":"Ребёнок организует семейный вечер: программа, роли для каждого, бюджет, который назовёте вы. После вечера обсудите, что получилось."},"why":"Ребёнок пробует отвечать за других: решать, распределять, договариваться.","tip":"Слушайтесь всерьёз. Если решение неудачное, пусть увидит результат сам.","need":{"3-5":"таймер на 15 минут","6-8":"лист бумаги, карандаш","9-12":"лист бумаги, бюджет, который назовёте вы"},"steps":{"3-5":["Объявите: 15 минут ты главный.","Ребёнок выбирает игру.","Говорит, кто что делает. Вы слушаетесь.","Когда таймер прозвенит, поблагодарите «капитана»."],"6-8":["Задача: спланировать семейную прогулку на час.","Ребёнок решает, куда идём и что берём.","Назначает, кто за что отвечает.","Сходите по его плану. Что сработало?"],"9-12":["Ребёнок организует семейный вечер.","Составляет программу и роли для каждого.","Укладывается в бюджет.","После вечера обсудите: что получилось и что он сделал бы иначе."]}},{"id":"leader-2","scale":"leader","title":"Новая игра","task":{"3-5":"Придумайте игру с мячом и одним правилом. Поиграйте. Ребёнок добавляет второе правило.","6-8":"Ребёнок придумывает игру с тремя правилами и объясняет её семье. Если кто-то не понял, правило надо сказать проще.","9-12":"Ребёнок придумывает настольную игру на листе бумаги: цель, ходы, как выиграть. Сыграйте и вместе исправьте одно слабое правило."},"why":"Придумать правило и объяснить его другим значит учиться управлять без крика.","tip":"Если правило непонятно, не додумывайте за ребёнка. Скажите: «Я не понял. Объясни проще».","need":{"3-5":"мяч","6-8":"любые игрушки или мяч","9-12":"лист бумаги, карандаш, кубик, фишки"},"steps":{"3-5":["Придумайте игру с мячом и одним правилом. Например: катаем только сидя.","Поиграйте две минуты.","Ребёнок добавляет второе правило.","Сыграйте по новым правилам."],"6-8":["Ребёнок придумывает игру с тремя правилами.","Объясняет её семье.","Кто-то не понял? Правило надо сказать проще.","Сыграйте один раунд."],"9-12":["Ребёнок рисует настольную игру: цель, ходы, как выиграть.","Сыграйте партию.","Найдите вместе одно слабое правило.","Исправьте его и сыграйте ещё раз."]}},{"id":"leader-3","scale":"leader","title":"Убеди меня","task":{"3-5":"Ребёнок выбирает между двумя вещами (яблоко или банан) и говорит почему. Одной причины достаточно.","6-8":"Ребёнок хочет что-то изменить дома (время сна, меню). Пусть назовёт три причины. Хорошие доводы принимаются.","9-12":"Спор по правилам: ребёнок 2 минуты защищает мнение, потом 2 минуты защищает противоположное. Какая сторона оказалась сильнее?"},"why":"Ребёнок учится добиваться своего доводами, а не настойчивостью.","tip":"Заранее решите, на что вы готовы согласиться. Последнее слово остаётся за вами.","need":{"3-5":"два предмета на выбор: яблоко и банан, две книги","6-8":"ничего не нужно","9-12":"таймер"},"steps":{"3-5":["Предложите выбор из двух.","Ребёнок выбирает и говорит почему.","Одной причины достаточно.","Повторите его довод вслух: «Ты выбрал банан, потому что он сладкий»."],"6-8":["Ребёнок называет одну вещь, которую хочет изменить дома.","Приводит три причины.","Вы отвечаете на каждую по существу.","Хорошие доводы принимаются. Решение за вами, и вы объясняете его."],"9-12":["Выберите тему спора.","Две минуты ребёнок защищает своё мнение.","Две минуты защищает противоположное.","Какая сторона оказалась сильнее и почему?"]}},{"id":"leader-4","scale":"leader","title":"Помощник капитана","task":{"3-5":"Сегодня главный вы, а ребёнок помощник: вы просите, он делает три дела. Поблагодарите за каждое.","6-8":"В игре ребёнок сегодня не водит, а помогает младшему или вам. Потом спросите: что было трудно?","9-12":"Ребёнок помогает другому человеку довести его идею до конца, не меняя её на свою. Потом обсудите, где хотелось перехватить."},"why":"Лидеру важно уметь быть вторым: слушать, помогать и не перехватывать.","tip":"Благодарите за конкретное дело: «Ты принёс всё сразу, и мы успели».","need":{"3-5":"три простых дела по дому","6-8":"любая игра","9-12":"чужая идея: проект брата, сестры или ваш"},"steps":{"3-5":["Объявите: сегодня главный я, а ты помощник.","Попросите о первом деле.","Поблагодарите и назовите второе, потом третье.","Скажите, чем его помощь вам помогла."],"6-8":["В игре ребёнок сегодня не водит.","Он помогает младшему или вам.","Сыграйте 10 минут.","Спросите: что было трудно? Что понравилось?"],"9-12":["Ребёнок выбирает, кому поможет.","Задача: довести чужую идею до конца, не меняя её на свою.","Работает 10 минут.","Обсудите: в какой момент хотелось сделать по-своему?"]}},{"id":"leader-5","scale":"leader","title":"Маленькое дело","task":{"3-5":"Игра в магазин: ребёнок продавец, вы покупатель. Он называет цену и считает «монеты» из бумаги.","6-8":"Ребёнок решает, что можно сделать для соседей или родных (открытки, печенье), и раздаёт задачи семье.","9-12":"Ребёнок придумывает маленькое дело на выходные: что делаем, для кого, сколько стоит. Считает расходы и результат."},"why":"Маленькое дело с ценой и результатом учит считать, планировать и думать о других.","tip":"Пусть ребёнок сам считает. Ошибку в расчёте найдите вместе.","need":{"3-5":"игрушки-«товары», бумажные «монеты»","6-8":"бумага, карандаши или продукты для печенья","9-12":"лист бумаги, калькулятор"},"steps":{"3-5":["Вырежьте заранее 10 бумажных монет.","Ребёнок раскладывает товары: он продавец.","Вы покупаете. Он называет цену и считает монеты.","Поменяйтесь ролями."],"6-8":["Ребёнок решает, что сделать для соседей или родных.","Раздаёт задачи семье.","Делаете вместе по его плану.","Он сам вручает результат."],"9-12":["Ребёнок придумывает маленькое дело на выходные.","Пишет: что делаем, для кого, сколько стоит.","Считает расходы.","После выходных подводит итог."]}},{"id":"helper-1","scale":"helper","title":"Что он чувствует","task":{"3-5":"Покажите лицом: радость, грусть, злость, удивление. Ребёнок угадывает и повторяет.","6-8":"Откройте книгу на картинке. Что чувствует каждый герой? По чему это видно?","9-12":"Посмотрите минуту фильма без звука. Ребёнок объясняет, что чувствуют герои и что, скорее всего, было сказано."},"why":"Ребёнок учится читать чувства по лицу и позе. Это основа эмпатии.","tip":"Называйте чувства и про себя тоже: «Я сейчас устал, это видно по плечам».","need":{"3-5":"зеркало (по желанию)","6-8":"книга с картинками","9-12":"минута из фильма без звука"},"steps":{"3-5":["Покажите лицом радость. Ребёнок угадывает.","Потом грусть, злость, удивление.","Ребёнок повторяет каждое выражение.","Теперь показывает он, а угадываете вы."],"6-8":["Откройте книгу на картинке с несколькими героями.","Что чувствует каждый?","По чему это видно: лицо, руки, поза?","Что сказал бы герой, если бы мог?"],"9-12":["Включите минуту фильма без звука.","Ребёнок объясняет, что чувствуют герои.","Говорит, что, скорее всего, было сказано.","Включите со звуком и сравните."]}},{"id":"helper-2","scale":"helper","title":"Тайное доброе дело","task":{"3-5":"Вместе сделайте сюрприз кому-то дома: рисунок под подушку или накрытый стол.","6-8":"Ребёнок выбирает человека и делает для него одно доброе дело так, чтобы тот не знал, кто это сделал.","9-12":"Ребёнок замечает, кому из близких сейчас непросто, и сам придумывает, чем помочь. Вы только обеспечиваете нужное."},"why":"Доброе дело без награды учит заботиться ради другого, а не ради похвалы.","tip":"Сохраните тайну. Не рассказывайте, кто сделал сюрприз.","need":{"3-5":"бумага, мелки или посуда для стола","6-8":"ничего не нужно","9-12":"то, что понадобится для помощи"},"steps":{"3-5":["Выберите, кому дома сделаете сюрприз.","Решите что: рисунок под подушку или накрытый стол.","Сделайте вместе, тихо.","Посмотрите издалека, как человек обрадуется."],"6-8":["Ребёнок выбирает человека.","Придумывает одно доброе дело для него.","Делает так, чтобы тот не узнал, кто это сделал.","Вечером расскажет вам, что почувствовал."],"9-12":["Ребёнок замечает, кому из близких сейчас непросто.","Сам придумывает, чем помочь.","Вы только даёте нужное.","Потом спросите: как он понял, что человеку нужна помощь?"]}},{"id":"helper-3","scale":"helper","title":"А чего хочу я","task":{"3-5":"Дайте выбор из двух: какую книгу читаем, какую чашку берём. Ребёнок выбирает сам и вслух.","6-8":"Сегодня ребёнок три раза говорит «я хочу…» и один раз вежливо говорит «нет». Потренируйтесь в игре.","9-12":"Разберите случай, когда ребёнок согласился, хотя не хотел. Как можно было отказать, не обидев? Отрепетируйте фразу."},"why":"Чуткому ребёнку важно уметь слышать и свои желания, а не только чужие.","tip":"Примите его «нет» спокойно. Так он узнаёт, что отказ не рушит отношения.","need":{"3-5":"две книги или две чашки","6-8":"ничего не нужно","9-12":"ничего не нужно"},"steps":{"3-5":["Предложите выбор из двух вещей.","Ребёнок выбирает сам и говорит вслух: «Я хочу эту».","Повторите выбор три раза за день в разных делах.","Не переспрашивайте и не предлагайте третий вариант."],"6-8":["Сыграйте в игру: вы предлагаете, он отвечает.","Задача: три раза сказать «я хочу…».","И один раз вежливо сказать «нет».","Скажите, что вам понравилось, как он отказал."],"9-12":["Вспомните случай, когда ребёнок согласился, хотя не хотел.","Обсудите: что мешало отказать?","Придумайте фразу, которая не обидит.","Отрепетируйте её вслух два раза."]}},{"id":"helper-4","scale":"helper","title":"Письмо спасибо","task":{"3-5":"Ребёнок рисует открытку человеку, который ему помог. Вы подписываете его словами.","6-8":"Ребёнок пишет три предложения спасибо учителю, тренеру или соседу: за что именно и что это изменило.","9-12":"Ребёнок пишет письмо человеку, которого давно не благодарил, и сам решает, как его передать."},"why":"Благодарность словами учит замечать, что для тебя делают другие.","tip":"Помогите вспомнить конкретное дело: «За что именно спасибо?»","need":{"3-5":"бумага, мелки","6-8":"лист бумаги, ручка","9-12":"бумага, ручка, конверт"},"steps":{"3-5":["Спросите: кто тебе недавно помог?","Ребёнок рисует открытку этому человеку.","Вы подписываете его словами, ничего не меняя.","Вручите вместе."],"6-8":["Ребёнок выбирает: учитель, тренер или сосед.","Пишет три предложения: за что спасибо и что это изменило.","Вы не правите текст, только ошибки по его просьбе.","Он сам передаёт записку."],"9-12":["Ребёнок вспоминает человека, которого давно не благодарил.","Пишет ему письмо.","Сам решает, как передать: лично, почтой, сообщением.","Передаёт на этой неделе."]}},{"id":"helper-5","scale":"helper","title":"Учитель на 10 минут","task":{"3-5":"Ребёнок учит игрушку или вас тому, что умеет: чистить зубы, надевать куртку.","6-8":"Ребёнок учит вас или младшего одной вещи, которую умеет хорошо. Вы стараетесь и иногда ошибаетесь.","9-12":"Ребёнок готовит десятиминутный урок для семьи по теме, в которой разбирается: объяснение, пример, вопрос на проверку."},"why":"Объясняя другому, ребёнок лучше понимает сам и чувствует себя умелым.","tip":"Будьте старательным учеником и иногда ошибайтесь. Пусть он вас поправит.","need":{"3-5":"игрушка, зубная щётка или куртка","6-8":"то, что ребёнок умеет хорошо","9-12":"лист бумаги для плана"},"steps":{"3-5":["Спросите: что ты умеешь сам?","Ребёнок учит игрушку или вас: чистить зубы, надевать куртку.","Сделайте ошибку. Пусть покажет, как правильно.","Поблагодарите учителя."],"6-8":["Ребёнок выбирает одно умение.","Учит вас или младшего по шагам.","Вы стараетесь и один раз ошибаетесь.","В конце покажите, чему научились."],"9-12":["Ребёнок выбирает тему, в которой разбирается.","Готовит урок на 10 минут: объяснение, пример, вопрос на проверку.","Проводит его для семьи.","Каждый называет одну вещь, которую узнал."]}},{"id":"mover-1","scale":"mover","title":"Полоса препятствий","task":{"3-5":"Подушки, стул, верёвка на полу: перешагнуть, проползти, пройти по линии. Три круга.","6-8":"Ребёнок сам строит дома полосу из 5 препятствий и проходит её на время. Вторая попытка быстрее?","9-12":"Ребёнок строит полосу из 6 этапов и придумывает правила штрафа. Проходите оба на время, три попытки, записываете результаты."},"why":"Полоса препятствий развивает координацию и умение планировать движение.","tip":"Уберите с пути острые углы и скользкие коврики. Хвалите за аккуратность, а не только за скорость.","need":{"3-5":"подушки, стул, верёвка или пояс","6-8":"подушки, стулья, верёвка, секундомер","9-12":"домашние предметы, секундомер, лист для записи"},"steps":{"3-5":["Положите верёвку на пол линией, рядом подушки и стул.","Покажите путь: перешагнуть, проползти под стулом, пройти по линии.","Ребёнок проходит три круга.","На последнем круге идите вместе."],"6-8":["Ребёнок сам строит полосу из 5 препятствий.","Проходит её на время.","Вторая попытка: получится быстрее?","Спросите, какое препятствие самое трудное."],"9-12":["Ребёнок строит полосу из 6 этапов.","Придумывает правила штрафа за ошибку.","Проходите оба, по три попытки.","Запишите результаты. Чей прогресс больше?"]}},{"id":"mover-2","scale":"mover","title":"Замри","task":{"3-5":"Музыка играет, все танцуют. Музыка стоп, все замирают. Кто простоит, не шевелясь, до счёта 5?","6-8":"Танцы и «замри» на одной ноге. Каждый раунд стоять на 2 секунды дольше.","9-12":"«Замри» с заданием: по команде принять позу (планка, ласточка, присед) и держать 20 секунд. Ребёнок придумывает позы для вас."},"why":"Игра «замри» тренирует умение остановиться по сигналу. Это основа самоконтроля.","tip":"Играйте вместе. Ребёнку важно видеть, что замереть трудно и вам.","need":{"3-5":"музыка","6-8":"музыка","9-12":"музыка, таймер"},"steps":{"3-5":["Включите музыку и танцуйте вместе.","Остановите музыку: все замирают.","Считайте вслух до 5.","Сыграйте пять раундов."],"6-8":["Танцуйте под музыку.","По остановке замрите на одной ноге.","Каждый раунд стойте на 2 секунды дольше.","До какого счёта дошли?"],"9-12":["По остановке музыки нужно принять позу: планка, ласточка или присед.","Держать 20 секунд.","Позы для вас придумывает ребёнок.","Пять раундов, потом поменяйтесь."]}},{"id":"mover-3","scale":"mover","title":"Новый трюк","task":{"3-5":"Подбросить мягкий мяч и поймать двумя руками. Потом хлопнуть, пока мяч в воздухе.","6-8":"Выберите трюк: 10 прыжков на скакалке подряд или набить воздушный шар 20 раз. Пять минут практики, потом зачёт. Лопнувший шар убирает взрослый.","9-12":"Ребёнок выбирает навык на неделю (жонглирование двумя мячами, стойка у стены, чеканка). Сегодня первый замер и план."},"why":"Ребёнок видит, что навык растёт от практики. Это меняет отношение к трудному.","tip":"Считайте попытки, а не ошибки: «Это была двенадцатая, стало ровнее».","need":{"3-5":"мягкий мяч","6-8":"скакалка или воздушный шар","9-12":"два мяча или стена, лист для записи"},"steps":{"3-5":["Ребёнок подбрасывает мяч и ловит двумя руками.","Пять раз подряд.","Усложните: хлопнуть, пока мяч в воздухе.","Сколько хлопков получилось?"],"6-8":["Выберите трюк: 10 прыжков подряд или набить шар 20 раз.","Пять минут практики.","Потом зачёт: считайте вслух.","Лопнувший шар убирает взрослый."],"9-12":["Ребёнок выбирает навык на неделю: жонглирование, стойка у стены, чеканка.","Сегодня первый замер: сколько получается сейчас.","Составляет план: 5 минут в день.","Повесьте лист с результатом на видное место."]}},{"id":"mover-4","scale":"mover","title":"Буквы телом","task":{"3-5":"Покажите телом зверей: как идёт медведь, прыгает заяц, ползёт змея. Ребёнок угадывает и повторяет.","6-8":"Ребёнок показывает телом буквы своего имени, вы угадываете. Потом показываете слово вдвоём.","9-12":"Таблица умножения в движении: ответ надо не сказать, а пропрыгать или отбить мячом. 10 примеров на скорость."},"why":"Движение помогает запоминать: буквы и числа, прожитые телом, держатся дольше.","tip":"Смейтесь вместе. Чем смешнее поза, тем лучше запомнится.","need":{"3-5":"свободное место","6-8":"свободное место","9-12":"мяч, таймер"},"steps":{"3-5":["Покажите, как идёт медведь.","Ребёнок угадывает и повторяет.","Потом заяц и змея.","Теперь зверя загадывает он."],"6-8":["Ребёнок показывает телом первую букву своего имени.","Вы угадываете.","Он показывает остальные буквы.","Покажите короткое слово вдвоём."],"9-12":["Вы называете пример из таблицы умножения.","Ответ надо пропрыгать или отбить мячом.","Десять примеров на скорость.","Поменяйтесь: примеры задаёт ребёнок."]}},{"id":"mover-5","scale":"mover","title":"Тихая минута после бега","task":{"3-5":"Две минуты побегайте и попрыгайте. Потом лягте на спину и положите игрушку на живот: как она качается?","6-8":"5 минут активной игры, затем 5 минут спокойного дела (пазл, рисунок). Заметьте вместе: легче сидеть после движения?","9-12":"Ребёнок проверяет на себе: читает 10 минут после разминки и 10 минут без неё. Когда запомнилось больше?"},"why":"Ребёнок на себе замечает, что после движения легче сосредоточиться. Этим можно пользоваться каждый день.","tip":"Используйте вывод: перед уроками или чтением дайте пять минут подвигаться.","need":{"3-5":"мягкая игрушка, коврик","6-8":"пазл или бумага и карандаши","9-12":"книга, таймер"},"steps":{"3-5":["Две минуты бегайте и прыгайте вместе.","Лягте на спину.","Положите ребёнку на живот игрушку.","Смотрите вместе, как она качается от дыхания."],"6-8":["Пять минут активной игры.","Пять минут спокойного дела: пазл или рисунок.","Спросите: легко ли сидеть сейчас?","Сравните с тем, как бывает без разминки."],"9-12":["Ребёнок читает 10 минут после разминки.","Пересказывает, что запомнил.","На другой день читает 10 минут без разминки.","Сравнивает: когда запомнилось больше?"]}}],"safety":"Задания выполняются вместе со взрослым. Ножницы, нож и горячее берёт взрослый."};
